
window.QRious = class {
  constructor(opts){
    const canvas = opts.element;
    const value = encodeURIComponent(opts.value || '');
    const size = opts.size || 260;
    canvas.width=size; canvas.height=size;
    const ctx = canvas.getContext('2d');
    const img = new Image();
    img.crossOrigin='anonymous';
    img.onload=()=>{ctx.clearRect(0,0,size,size);ctx.drawImage(img,0,0,size,size);};
    img.onerror=()=>{throw new Error('QR render failed');};
    img.src='https://api.qrserver.com/v1/create-qr-code/?size='+size+'x'+size+'&data='+value;
  }
};
